```hcl
resource "aap_host" "host" {
  inventory_id = data.aap_inventory.inventory.id
  name         = aws_instance.instance.public_ip
  lifecycle {
    action_trigger {
      events  = [after_create]
      actions = [action.aap_eda_eventstream_post.event_post]
    }
  }
}
data "aap_eda_eventstream" "es" { name = "TF Actions Event Stream" }
action "aap_eda_eventstream_post" "event_post" {
  config {
    limit             = "all"
    template_type     = "job"   # or workflow_job
    job_template_name = "Demo Job Template"
    organization_name = "Default"
    event_stream_config = {
      username = var.event_stream_username
      password = var.event_stream_password
      url      = data.aap_eda_eventstream.es.url
    }
  }
}
```
